import re

# ============================================
# CÍRCULO 17 = CENTRO DA MAPA
# ============================================

center_x = float(SEGMENTS[12]["pinX"])
center_y = float(SEGMENTS[12]["pinY"])

scale = 0.6

print("Centro original:")
print("X =", center_x)
print("Y =", center_y)


def fmt(val):
    v = round(val, 1)
    return str(int(v)) if v == int(v) else str(v)


def transform_x(x):
    return fmt((float(x) - center_x) * scale)


def transform_y(y):
    return fmt((float(y) - center_y) * scale)


# ============================================
# GERAR SEGMENTS
# ============================================

print("const SEGMENTS = {")

for k in sorted(SEGMENTS.keys()):
    v = SEGMENTS[k]

    new_path = re.sub(
        r'([ML])\s*(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)',
        lambda m:
            f"{m.group(1)} "
            f"{transform_x(m.group(2))},"
            f"{transform_y(m.group(3))}",
        v["path"]
    )

    new_pinX = transform_x(v["pinX"])
    new_pinY = transform_y(v["pinY"])

    print(
        f'  {k}: {{ '
        f'artery: "{v["artery"]}", '
        f'name: "{v["name"]}", '
        f'path: "{new_path}", '
        f'pinX: {new_pinX}, '
        f'pinY: {new_pinY} '
        f'}},'
    )

print("};")

# ============================================
# VERIFICAÇÃO
# ============================================

print()
print("Círculo 17 depois da transformação:")
print(
    "pinX =",
    transform_x(SEGMENTS["17"]["pinX"])
)

print(
    "pinY =",
    transform_y(SEGMENTS["17"]["pinY"])
)
